package dev.zomboid.hordes;
import java.util.*;import net.minecraft.world.item.*;import fixture.*;import fixture.Game.*;import mod.cdv.tnpc.tactical.StarterGear;import net.minecraft.world.entity.EquipmentSlot;
public class NerfChecks{
 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static ItemStack stack(String id,int n){return new ItemStack(new Item(id),n);}
 public static class SpecialList extends ArrayList<Object>{}public static class Chest{}public record Params(World getLevel){}
 public static void main(String[]args)throws Exception{
  Map<String,Double>defaults=WorldTuning.snapshot();ok(defaults.get("loot_arma_rara")==2&&defaults.get("bandidos_armados")==2,"rare weapons and mostly unarmed default");
  Map<String,Double>edited=new HashMap<>(defaults);edited.put("densidad",2.7);edited.put("mutantes",12.);edited.put("velocidad_brutos",2.);edited.put("zombis_militares",18.);edited.put("ia_oido",.4);edited.put("epicos",16.);edited.put("armas_cargadas",100.);ScarcityControls.prepare(edited);for(String k:new String[]{"densidad","mutantes","velocidad_brutos","zombis_militares","ia_oido"})ok(edited.get(k).equals(Map.of("densidad",2.7,"mutantes",12.,"velocidad_brutos",2.,"zombis_militares",18.,"ia_oido",.4).get(k)),"loot restore preserves zombie setting "+k);ok(edited.get("epicos")==.6&&edited.get("armas_cargadas")==10,"old overpowered loot controls reset");for(var e:edited.entrySet())WorldTuning.checked(e.getKey(),e.getValue());
  String[][]old=new String[16][];for(int i=0;i<16;i++)old[i]=new String[0];String[][]keys=ScarcityPanel.rows(old,"KEYS"),labels=ScarcityPanel.rows(old,"LABELS"),hints=ScarcityPanel.rows(old,"HINTS");ok(keys.length==17&&keys[16].length==10,"scarcity page fits native layout");ok(labels[16].length==10&&hints[16].length==10,"every new control explained");for(String k:keys[16])ok(defaults.containsKey(k),"control in complete schema");
  World w=new World();List<Object>input=new ArrayList<>();for(int i=0;i<40;i++){ItemStack gun=new ItemStack(new GunItem(),1);gun.ammo=64;gun.component="generated gun "+i;input.add(gun);}for(int i=0;i<8;i++)input.add(new ItemStack(new ArmorItem("minecraft:diamond_chestplate"),1));input.add(new ItemStack(new AmmoItem(),160));for(int i=0;i<15;i++)input.add(stack("minecraft:bread",64));input.add(stack("minecraft:iron_pickaxe",4));input.add(stack("minecraft:leather_chestplate",1));
  for(int q=0;q<=5;q++){int armed=0;for(int sample=0;sample<500;sample++){List<Object>out=LootNerf.filter(input,w,q,List.of());int guns=0,armors=0,ammo=0,supplies=0;for(Object o:out){ItemStack s=(ItemStack)o;switch(LootNerf.kind(s)){case LootNerf.WEAPON->{guns++;ok(s.count==1&&s.ammo<=4&&!s.barrel,"generated gun no full free magazine");}case LootNerf.ARMOR->armors++;case LootNerf.AMMO->{ammo++;ok(s.count<=LootNerf.ammoCap(q),"ammo pile bounded by tier");}case LootNerf.OTHER,LootNerf.TOOL->{supplies++;ok(s.count<=1+q/2,"supplies no large stacks");}}}ok(guns<=1&&armors<=1&&ammo<=1,"one draw per equipment category despite 40 candidate guns");ok(supplies<=2+q,"supplies bounded from common to mythic");if(guns>0)armed++;}ok(armed<70,"many candidates do not multiply weapon chance");}
  ItemStack owned=new ItemStack(new GunItem(),1);owned.ammo=50;owned.component="owned legendary data";List<Object>kept=LootNerf.filter(List.of(owned),w,0,List.of(owned));ok(kept.size()==1&&((ItemStack)kept.get(0)).ammo==50&&((ItemStack)kept.get(0)).component.equals(owned.component),"actual held gear components retained");SpecialList original=new SpecialList();original.addAll(input);ok(LootNerf.container(original,new Chest(),new Params(w))==original,"original collection type retained for mixin cast");ok(original.size()<input.size(),"chest receives scarcity");ok(dev.zomboid.remains.ScarcityCompat33.synthetic(new Object(),"populate",new Object[0])==null,"no bonus equipment invented on NPC death");
  Actor npc=new Actor();StarterGear.outfit(npc,new Random(){public double nextDouble(){return .99;}});ok(npc.getMainHandItem().isEmpty()&&npc.getOffhandItem().isEmpty(),"normal new bandit empty hands");ok(npc.bag.isEmpty()&&npc.getItemBySlot(EquipmentSlot.CHEST).isEmpty(),"no starting arsenal or combat armor");ok(npc.tag.getBoolean("TacZNpcCombatV12"),"police automatic pistol and free ammo disabled");ItemStack found=new ItemStack(new GunItem(),1);found.component="looted weapon";npc.setItemSlot(EquipmentSlot.MAINHAND,found);StarterGear.outfit(npc,new Random());ok(npc.getMainHandItem()==found,"later outfit calls never remove farmed gear");
  Actor oldNpc=new Actor();oldNpc.tag.putBoolean("TacZNpcLoadoutV11",true);oldNpc.setItemSlot(EquipmentSlot.MAINHAND,owned);oldNpc.bag.add(stack("minecraft:diamond",5));StarterGear.outfit(oldNpc,new Random());ok(oldNpc.getMainHandItem()==owned&&oldNpc.bag.size()==1,"existing NPC inventory untouched");Actor testNpc=new Actor();testNpc.tag.putBoolean("np15_test",true);testNpc.setItemSlot(EquipmentSlot.MAINHAND,owned);StarterGear.outfit(testNpc,new Random());ok(testNpc.getMainHandItem()==owned,"test NPC owner loadout preserved");
  Actor lucky=new Actor();StarterGear.outfit(lucky,new Random(){public double nextDouble(){return 0;}});ok(!lucky.getMainHandItem().isEmpty()&&lucky.getMainHandItem().ammo<=4,"rare armed starter few bullets");ok(StarterGear.armorSlot(new ItemStack(new ArmorItem("minecraft:iron_chestplate"),1))==EquipmentSlot.CHEST,"scavenged vanilla armor can be equipped");
  Actor reloader=npc;ItemStack gun=new ItemStack(new GunItem(),1);gun.ammo=0;reloader.setItemSlot(EquipmentSlot.MAINHAND,gun);ok(StarterGear.reload(reloader)&&reloader.tag.getLong("Scarcity33ReloadAt")==0,"empty bag cannot create ammunition");ItemStack compatible=new ItemStack(new AmmoItem(),6),wrong=new ItemStack(new AmmoItem(),40);wrong.ammoId="tacz:556";reloader.bag=new ArrayList<>(List.of(compatible,wrong));ok(StarterGear.ammunition(10000,reloader)==6,"AI sees actual compatible rounds");StarterGear.reload(reloader);ok(reloader.tag.getLong("Scarcity33ReloadAt")==40,"reload waits configured two seconds");StarterGear.tick(reloader);ok(reloader.getMainHandItem().ammo==0,"not instantly loaded");reloader.world.time=40;StarterGear.tick(reloader);ok(reloader.getMainHandItem().ammo==6&&reloader.bag.size()==1&&((ItemStack)reloader.bag.get(0)).count==40,"real compatible ammo transferred once incompatible retained");StarterGear.tick(reloader);ok(reloader.getMainHandItem().ammo==6,"no repeated duplication");
  reloader.bag=new ArrayList<>(List.of(new ItemStack(new AmmoItem(),6)));reloader.getMainHandItem().ammo=0;StarterGear.reload(reloader);reloader.setItemSlot(EquipmentSlot.MAINHAND,stack("minecraft:wooden_sword",1));reloader.world.time=80;StarterGear.tick(reloader);ok(((ItemStack)reloader.bag.get(0)).count==6,"weapon switch cancels ammo transfer");
  int armed=0;for(int i=0;i<1000;i++){Actor a=new Actor();StarterGear.outfit(a,new Random(i*7919L));if(!a.getMainHandItem().isEmpty())armed++;}ok(armed>5&&armed<40,"roughly 98 percent of new bandits unarmed");System.out.println("NERF_CHECKS="+checks);
 }
}
